<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>2048</title>
<style>
  :root{
    --bg:#0d1015;
    --panel:#151a23;
    --edge:#262f3e;
    --cell:#1f2632;
    --ink:#e9eef6;
    --muted:#8792a6;
    --accent:#6fb0f0;
  }
  *{box-sizing:border-box;margin:0;padding:0}
  html,body{height:100%}
  body{
    background:
      radial-gradient(900px 600px at 50% -10%, #18202e 0%, rgba(24,32,46,0) 65%),
      var(--bg);
    color:var(--ink);
    font-family:ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;
    display:flex;align-items:center;justify-content:center;
    min-height:100vh;padding:24px;
    -webkit-font-smoothing:antialiased;
  }
  .wrap{width:min(92vw,420px)}

  header{display:flex;align-items:flex-end;justify-content:space-between;gap:12px;margin-bottom:8px}
  .logo{font-size:46px;font-weight:800;letter-spacing:-2px;line-height:.95;color:#f3f6fb}
  .logo b{color:var(--accent);font-weight:800}
  .stats{display:flex;gap:8px}
  .stat{min-width:78px;background:var(--panel);border:1px solid var(--edge);border-radius:10px;padding:7px 12px 8px;text-align:center}
  .stat .lbl{display:block;font-size:10px;font-weight:600;letter-spacing:.14em;text-transform:uppercase;color:var(--muted);margin-bottom:2px}
  .stat .val{font-size:20px;font-weight:700;font-variant-numeric:tabular-nums;line-height:1.1}

  .sub{color:var(--muted);font-size:13px;margin:0 0 14px}
  .sub strong{color:#c6d2e4;font-weight:600}

  #board{
    display:grid;grid-template-columns:repeat(4,1fr);gap:10px;
    background:var(--panel);border:1px solid var(--edge);
    border-radius:14px;padding:10px;aspect-ratio:1/1;
    user-select:none;-webkit-user-select:none;touch-action:none;
    transition:opacity .3s ease;
  }
  #board.dead{opacity:.5}
  .cell{
    background:var(--cell);border-radius:9px;
    display:flex;align-items:center;justify-content:center;
    font-weight:800;font-variant-numeric:tabular-nums;
    font-size:clamp(22px,7vw,36px);
    box-shadow:inset 0 2px 8px rgba(0,0,0,.28);
    transition:background-color .12s ease;
  }
  .cell[data-len="3"]{font-size:clamp(19px,6vw,30px)}
  .cell[data-len="4"]{font-size:clamp(16px,5vw,24px)}
  .cell[data-len="5"]{font-size:clamp(13px,4vw,19px)}

  .cell[class*=" t-"]{box-shadow:inset 0 -3px 0 rgba(0,0,0,.22),inset 0 1px 0 rgba(255,255,255,.07)}
  .t-2   {background:#37405a;color:#dee5f4}
  .t-4   {background:#3f4c6e;color:#dee5f4}
  .t-8   {background:#3563a8;color:#f1f5fd}
  .t-16  {background:#3f79cf;color:#f1f5fd}
  .t-32  {background:#4f93e6;color:#0c1a2e}
  .t-64  {background:#5fb7f5;color:#0c1a2e}
  .t-128 {background:#54d6c2;color:#08211d}
  .t-256 {background:#5ee6a0;color:#07271a}
  .t-512 {background:#ffd166;color:#2b2005}
  .t-1024{background:#ffa94d;color:#2b1605}
  .t-2048{background:#ff6b6b;color:#2b0d0d}
  .t-4096{background:#f06bb3;color:#2b0a1d}

  @keyframes pop{from{transform:scale(.35);opacity:0}to{transform:scale(1);opacity:1}}
  @keyframes bump{0%{transform:scale(1)}40%{transform:scale(1.16)}100%{transform:scale(1)}}
  .cell.spawn{animation:pop .16s ease-out}
  .cell.merge{animation:bump .2s ease-out}
  @media (prefers-reduced-motion:reduce){.cell.spawn,.cell.merge{animation:none}}

  .foot{display:flex;align-items:center;justify-content:space-between;margin-top:14px}
  #reset{
    appearance:none;background:#222b3c;border:1px solid #33405a;color:var(--ink);
    font:inherit;font-size:14px;font-weight:600;letter-spacing:.01em;
    padding:9px 16px;border-radius:10px;cursor:pointer;
    transition:background-color .15s ease,border-color .15s ease,transform .06s ease;
  }
  #reset:hover{background:#2a3550;border-color:#41527a}
  #reset:active{transform:translateY(1px)}
  #reset:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
  .hint{color:var(--muted);font-size:12.5px;letter-spacing:.04em}

  .statusline{min-height:20px;margin-top:8px;font-size:13px;color:#e8a0a8;text-align:center}
</style>
</head>
<body>
<main class="wrap">
  <header>
    <div class="logo">20<b>48</b></div>
    <div class="stats">
      <div class="stat"><span class="lbl">Score</span><span class="val" id="score">0</span></div>
      <div class="stat"><span class="lbl">Best</span><span class="val" id="best">0</span></div>
    </div>
  </header>
  <p class="sub">Slide with the <strong>arrow keys</strong> &mdash; equal tiles merge and add to your score.</p>
  <div id="board" aria-label="2048 board"></div>
  <div class="foot">
    <button id="reset" type="button">New game</button>
    <span class="hint">&#8592;&nbsp;&nbsp;&#8593;&nbsp;&nbsp;&#8595;&nbsp;&nbsp;&#8594;</span>
  </div>
  <p class="statusline" id="status" role="status"></p>
</main>

<script>
(function () {
  'use strict';
  const SIZE = 4;

  const boardEl  = document.getElementById('board');
  const scoreEl  = document.getElementById('score');
  const bestEl   = document.getElementById('best');
  const statusEl = document.getElementById('status');

  const cells = [];
  for (let i = 0; i < SIZE * SIZE; i++) {
    const d = document.createElement('div');
    d.className = 'cell';
    boardEl.appendChild(d);
    cells.push(d);
  }

  let grid = emptyGrid();
  let scoreVal = 0;
  let bestVal = 0;
  let fx = { spawns: [], merges: [] };

  function emptyGrid() {
    return Array.from({ length: SIZE }, () => new Array(SIZE).fill(0));
  }

  function spawnTile() {
    const empties = [];
    for (let r = 0; r < SIZE; r++)
      for (let c = 0; c < SIZE; c++)
        if (grid[r][c] === 0) empties.push([r, c]);
    if (!empties.length) return;
    const [r, c] = empties[(Math.random() * empties.length) | 0];
    grid[r][c] = Math.random() < 0.9 ? 2 : 4;
    fx.spawns.push([r, c]);
  }

  // Slide one line toward index 0; each tile merges at most once per move.
  function collapse(line) {
    const out = [];
    const mergedAt = [];
    let gained = 0;
    let canMerge = true;
    for (let k = 0; k < line.length; k++) {
      const v = line[k];
      if (v === 0) continue;
      if (canMerge && out.length > 0 && out[out.length - 1] === v) {
        out[out.length - 1] = v * 2;
        mergedAt.push(out.length - 1);
        gained += v * 2;
        canMerge = false;
      } else {
        out.push(v);
        canMerge = true;
      }
    }
    while (out.length < line.length) out.push(0);
    return { out, mergedAt, gained };
  }

  // (line i, position j along the line, j=0 at the destination edge) <-> (row, col)
  const DIRS = {
    left : { get: (g, i, j) => g[i][j],          set: (g, i, j, v) => { g[i][j] = v; } },
    right: { get: (g, i, j) => g[i][SIZE - 1 - j], set: (g, i, j, v) => { g[i][SIZE - 1 - j] = v; } },
    up   : { get: (g, i, j) => g[j][i],          set: (g, i, j, v) => { g[j][i] = v; } },
    down : { get: (g, i, j) => g[SIZE - 1 - j][i], set: (g, i, j, v) => { g[SIZE - 1 - j][i] = v; } }
  };

  function coordsOf(dir, i, j) {
    switch (dir) {
      case 'left':  return [i, j];
      case 'right': return [i, SIZE - 1 - j];
      case 'up':    return [j, i];
      case 'down':  return [SIZE - 1 - j, i];
    }
    return [i, j];
  }

  function differs(a, b) {
    for (let r = 0; r < SIZE; r++)
      for (let c = 0; c < SIZE; c++)
        if (a[r][c] !== b[r][c]) return true;
    return false;
  }

  function move(dir) {
    const key = typeof dir === 'string' ? dir.toLowerCase() : '';
    const d = DIRS[key];
    if (!d) return false;

    const before = grid.map(row => row.slice());
    const next = emptyGrid();
    let gained = 0;
    fx = { spawns: [], merges: [] };

    for (let i = 0; i < SIZE; i++) {
      const line = [];
      for (let j = 0; j < SIZE; j++) line.push(d.get(grid, i, j));
      const res = collapse(line);
      gained += res.gained;
      for (let j = 0; j < SIZE; j++) {
        d.set(next, i, j, res.out[j]);
        if (res.mergedAt.indexOf(j) !== -1) {
          fx.merges.push(coordsOf(key, i, j));
        }
      }
    }

    if (!differs(next, before)) { render(); return false; }

    grid = next;
    scoreVal += gained;
    if (scoreVal > bestVal) { bestVal = scoreVal; bestEl.textContent = bestVal; }
    spawnTile();
    render();
    updateStatus();
    return true;
  }

  function render() {
    for (let r = 0; r < SIZE; r++) {
      for (let c = 0; c < SIZE; c++) {
        const el = cells[r * SIZE + c];
        const v = grid[r][c];
        el.textContent = v ? String(v) : '';
        el.className = 'cell' + (v ? ' t-' + Math.min(v, 4096) : '');
        if (v) el.dataset.len = String(v).length;
        else el.removeAttribute('data-len');
        if (fx.spawns.some(s => s[0] === r && s[1] === c)) el.classList.add('spawn');
        if (fx.merges.some(m => m[0] === r && m[1] === c)) el.classList.add('merge');
      }
    }
    scoreEl.textContent = scoreVal;
  }

  function movesAvailable() {
    for (let r = 0; r < SIZE; r++)
      for (let c = 0; c < SIZE; c++) {
        if (grid[r][c] === 0) return true;
        if (c + 1 < SIZE && grid[r][c] === grid[r][c + 1]) return true;
        if (r + 1 < SIZE && grid[r][c] === grid[r + 1][c]) return true;
      }
    return false;
  }

  function updateStatus() {
    const alive = movesAvailable();
    boardEl.classList.toggle('dead', !alive);
    statusEl.textContent = alive ? '' : 'No moves left \u2014 start a new game.';
  }

  function reset() {
    grid = emptyGrid();
    scoreVal = 0;
    fx = { spawns: [], merges: [] };
    spawnTile();
    spawnTile();
    render();
    updateStatus();
  }

  function setBoard(arr) {
    grid = emptyGrid();
    for (let r = 0; r < SIZE; r++)
      for (let c = 0; c < SIZE; c++) {
        const row = arr && arr[r];
        const v = row ? Number(row[c]) : 0;
        grid[r][c] = Number.isFinite(v) ? v : 0;
      }
    fx = { spawns: [], merges: [] };
    render();
    updateStatus();
  }

  // ---- wiring ----
  document.getElementById('reset').addEventListener('click', reset);

  const KEYS = {
    ArrowLeft: 'left', ArrowRight: 'right', ArrowUp: 'up', ArrowDown: 'down',
    a: 'left', d: 'right', w: 'up', s: 'down',
    A: 'left', D: 'right', W: 'up', S: 'down'
  };
  window.addEventListener('keydown', (e) => {
    const dir = KEYS[e.key];
    if (!dir) return;
    e.preventDefault();
    move(dir);
  });

  // optional swipe support
  let ptr = null;
  boardEl.addEventListener('pointerdown', (e) => { ptr = { x: e.clientX, y: e.clientY }; });
  window.addEventListener('pointerup', (e) => {
    if (!ptr) return;
    const dx = e.clientX - ptr.x, dy = e.clientY - ptr.y;
    ptr = null;
    const ax = Math.abs(dx), ay = Math.abs(dy);
    if (Math.max(ax, ay) < 24) return;
    move(ax > ay ? (dx > 0 ? 'right' : 'left') : (dy > 0 ? 'down' : 'up'));
  });
  window.addEventListener('pointercancel', () => { ptr = null; });

  // ---- public API ----
  window.game = {
    size: SIZE,
    reset: reset,
    move: move,
    board: () => grid.map(row => row.slice()),
    setBoard: setBoard,
    score: () => scoreVal
  };

  reset();
})();
</script>
</body>
</html>
